function Glow({ id }: { id: string }) {
  return (
    <linearGradient id={id} x1="0" y1="-1540" x2="0" y2="140" gradientUnits="userSpaceOnUse">
      <stop offset="0" stop-color="#F2B45C" />
      <stop offset="1" stop-color="#C47621" />
    </linearGradient>
  );
}

/** Full lockup: mark + wordmark. Sized by height; width follows. */
export function Logo({ height = 26 }: { height?: number }) {
  return (
    <svg
      class="luma-logo"
      height={height}
      viewBox="-308 -1848 7397 2296"
      fill="none"
      role="img"
      aria-label="Luma"
    >
      <defs>
        <Glow id="luma-logo-glow" />
      </defs>
      <path d={SPARKLE} fill="url(#luma-logo-glow)" />
      <path d={WORD} fill="currentColor" transform="translate(2296 0)" />
    </svg>
  );
}

/** The mark alone — a single glint of light. */
export function Mark({ size = 20 }: { size?: number }) {
  return (
    <svg
      class="luma-mark"
      width={size}
      height={size}
      viewBox="-308 -1848 2296 2296"
      fill="none"
      aria-hidden="true"
    >
      <defs>
        <Glow id="luma-mark-glow" />
      </defs>
      <path d={SPARKLE} fill="url(#luma-mark-glow)" />
    </svg>
  );
}
